import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';
import { EventEmitter as NodeEventEmitter } from 'node:events';

export class Disposable {
  constructor(callOnDispose) {
    this._callOnDispose = callOnDispose;
  }
  static from(...disposables) {
    return new Disposable(() => {
      for (const d of disposables) {
        if (d && typeof d.dispose === 'function') {
          d.dispose();
        }
      }
    });
  }
  dispose() {
    if (typeof this._callOnDispose === 'function') {
      const fn = this._callOnDispose;
      this._callOnDispose = undefined;
      fn();
    }
  }
}

export class EventEmitter {
  constructor() {
    this._emitter = new NodeEventEmitter();
    this.event = (listener, thisArgs, disposables) => {
      const bound = thisArgs ? listener.bind(thisArgs) : listener;
      this._emitter.on('event', bound);
      const disp = new Disposable(() => this._emitter.off('event', bound));
      if (Array.isArray(disposables)) {
        disposables.push(disp);
      }
      return disp;
    };
  }
  fire(data) {
    this._emitter.emit('event', data);
  }
  dispose() {
    this._emitter.removeAllListeners();
  }
}

export class CancellationTokenSource {
  constructor() {
    this._emitter = new EventEmitter();
    this.token = {
      isCancellationRequested: false,
      onCancellationRequested: this._emitter.event,
    };
  }
  cancel() {
    if (!this.token.isCancellationRequested) {
      this.token.isCancellationRequested = true;
      this._emitter.fire();
    }
  }
  dispose() {
    this._emitter.dispose();
  }
}

export class Uri {
  constructor(scheme, authority, fsPath, query = '', fragment = '') {
    this.scheme = scheme;
    this.authority = authority;
    this.fsPath = fsPath;
    this.path = fsPath.replace(/\\/g, '/');
    this.query = query;
    this.fragment = fragment;
  }
  static file(fsPath) {
    const resolved = path.resolve(fsPath);
    return new Uri('file', '', resolved);
  }
  static parse(value) {
    if (value.startsWith('file://')) {
      try {
        return Uri.file(fileURLToPath(value));
      } catch {
        const stripped = value.replace(/^file:\/\/\/?/, '');
        return new Uri('file', '', stripped);
      }
    }
    const url = new URL(value);
    return new Uri(url.protocol.replace(':', ''), url.host, url.pathname, url.search.slice(1), url.hash.slice(1));
  }
  static joinPath(base, ...segments) {
    return Uri.file(path.join(base.fsPath, ...segments));
  }
  with(change) {
    return new Uri(
      change.scheme ?? this.scheme,
      change.authority ?? this.authority,
      change.path ?? this.fsPath,
      change.query ?? this.query,
      change.fragment ?? this.fragment,
    );
  }
  toString() {
    if (this.scheme === 'file') {
      return pathToFileURL(this.fsPath).toString();
    }
    return `${this.scheme}://${this.authority}${this.path}`;
  }
  toJSON() {
    return this.toString();
  }
}

export class Position {
  constructor(line, character) {
    this.line = line;
    this.character = character;
  }
  isBefore(other) {
    return this.line < other.line || (this.line === other.line && this.character < other.character);
  }
  isBeforeOrEqual(other) {
    return this.isBefore(other) || this.isEqual(other);
  }
  isAfter(other) {
    return !this.isBeforeOrEqual(other);
  }
  isAfterOrEqual(other) {
    return !this.isBefore(other);
  }
  isEqual(other) {
    return this.line === other.line && this.character === other.character;
  }
  translate(lineDelta = 0, characterDelta = 0) {
    return new Position(this.line + lineDelta, this.character + characterDelta);
  }
  with(line = this.line, character = this.character) {
    return new Position(line, character);
  }
}

export class Range {
  constructor(startLineOrPos, startCharOrEndPos, endLine, endChar) {
    if (startLineOrPos instanceof Position || (typeof startLineOrPos === 'object' && startLineOrPos !== null)) {
      this.start = new Position(startLineOrPos.line, startLineOrPos.character);
      this.end = new Position(startCharOrEndPos.line, startCharOrEndPos.character);
    } else {
      this.start = new Position(startLineOrPos, startCharOrEndPos);
      this.end = new Position(endLine, endChar);
    }
  }
  get isEmpty() {
    return this.start.isEqual(this.end);
  }
  contains(posOrRange) {
    if ('start' in posOrRange) {
      return this.contains(posOrRange.start) && this.contains(posOrRange.end);
    }
    return this.start.isBeforeOrEqual(posOrRange) && posOrRange.isBeforeOrEqual(this.end);
  }
}

export class Selection extends Range {
  constructor(anchor, active) {
    super(anchor, active);
    this.anchor = anchor;
    this.active = active;
  }
}

export class Location {
  constructor(uri, rangeOrPosition) {
    this.uri = uri;
    this.range =
      rangeOrPosition instanceof Range
        ? rangeOrPosition
        : new Range(rangeOrPosition, rangeOrPosition);
  }
}

export class TextEdit {
  constructor(range, newText) {
    this.range = range;
    this.newText = newText;
  }
  static replace(range, newText) {
    return new TextEdit(range, newText);
  }
  static insert(position, newText) {
    return new TextEdit(new Range(position, position), newText);
  }
  static delete(range) {
    return new TextEdit(range, '');
  }
}

export class WorkspaceEdit {
  constructor() {
    this._edits = new Map();
    this._fileOps = [];
  }
  replace(uri, range, newText) {
    const key = uri.toString();
    const list = this._edits.get(key) ?? [];
    list.push({ uri, edit: TextEdit.replace(range, newText) });
    this._edits.set(key, list);
  }
  insert(uri, position, newText) {
    const key = uri.toString();
    const list = this._edits.get(key) ?? [];
    list.push({ uri, edit: TextEdit.insert(position, newText) });
    this._edits.set(key, list);
  }
  delete(uri, range) {
    const key = uri.toString();
    const list = this._edits.get(key) ?? [];
    list.push({ uri, edit: TextEdit.delete(range) });
    this._edits.set(key, list);
  }
  renameFile(oldUri, newUri, options = {}) {
    this._fileOps.push({ type: 'rename', oldUri, newUri, options });
  }
  deleteFile(uri, options = {}) {
    this._fileOps.push({ type: 'delete', uri, options });
  }
  createFile(uri, options = {}) {
    this._fileOps.push({ type: 'create', uri, options });
  }
  getFileOperations() {
    return [...this._fileOps];
  }
  get(uri) {
    return (this._edits.get(uri.toString()) ?? []).map((e) => e.edit);
  }
  entries() {
    const out = [];
    for (const items of this._edits.values()) {
      if (items.length > 0) {
        out.push([items[0].uri, items.map((i) => i.edit)]);
      }
    }
    return out;
  }
  get size() {
    return this._edits.size + this._fileOps.length;
  }
}

